<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue';
import { api } from '../api';
import { type Row, statusNames, contactStates, pledgeStates, formatTime, localDateInput, fromLocalInput, requestId } from '../../shared/domain';
import Icon from './Icon.vue';
import { useRequestScope } from '../../shared/useRequestScope';
const props = defineProps<{ mode: 'crowdfunding' | 'contacts'; user: Row | null; manage?: boolean; target?: Row | null }>();
const emit = defineEmits<{ (event: 'join'): void; (event: 'clear-target'): void }>();
const rows = ref<Row[]>([]), mine = ref<Row[]>([]), pledges = ref<Row[]>([]), managed = ref<Row[]>([]), members = ref<Row[]>([]), details = ref<Row[]>([]);
const tab = ref(props.manage ? 'manage' : 'public'), modal = ref(''), form = ref<Row>({}), selected = ref<Row>({}), busy = ref(false), error = ref(''), message = ref(''), dialog = ref<HTMLDialogElement | null>(null);
const staff = computed(() => props.user && ['superadmin', 'admin', 'organizer'].includes(props.user.role));
const visible = computed(() => tab.value === 'mine' ? mine.value : tab.value === 'manage' ? managed.value : rows.value);
const loading = ref(false);
let generation = 0, detailGeneration = 0;
const scope = useRequestScope();
onUnmounted(() => { ++generation; });
async function load() { const version = ++generation;loading.value = true;error.value = '';try {
  if (props.mode === 'crowdfunding') { const data = await api('/crowdfunding');if (version !== generation) return;rows.value = data;if (props.user) { const data = await Promise.all([api('/my/crowdfunding'), api('/my/pledges')]);if (version !== generation) return;[mine.value, pledges.value] = data; }if (staff.value) { const data = await api('/admin/crowdfunding');if (version !== generation) return;managed.value = data; } }
  else if (props.user) { const data = await api('/my/contact-exchanges');if (version !== generation) return;rows.value = data;if (props.user.status === 'approved') { const data = await api('/members');if (version !== generation) return;members.value = data.filter((m: Row) => m.id !== props.user?.id); } }
} catch(e) { if (version === generation) error.value = (e as Error).message; } finally { if (version === generation) loading.value = false; } }
function member() { if (!props.user || props.user.status !== 'approved') { emit('join');return false; }return true; }
async function open(kind: string, data: Row = {}) { const current = scope.capture();const detailVersion = ++detailGeneration; error.value = '';form.value = { ...data };modal.value = kind;await nextTick();if (!current() || detailVersion !== detailGeneration) return;if (!dialog.value?.open) dialog.value?.showModal(); }
function close() { if (busy.value) return;++detailGeneration;dialog.value?.close();modal.value = '';emit('clear-target'); }
function create() { if (!member()) return;open(props.mode === 'contacts' ? 'contact' : 'project', props.mode === 'contacts' ? { recipientId: '', contact: '', message: '' } : { title: '', type: '物资', unit: '件', goal: 10, purpose: '', description: '', endsAt: localDateInput(new Date(Date.now() + 14 * 86400000)), consent: false }); }
async function act(action: () => Promise<any>, text: string, keep = false) {
  if (busy.value) return;const current = scope.capture(), id = selected.value.id;busy.value = true;error.value = '';
  try { await action();if (!current()) return;busy.value = false;if (!keep) close();message.value = text;await load();if (current() && keep && selected.value.id === id && modal.value === 'supporters') { const data = await api('/crowdfunding/' + id + '/pledges');if (current() && selected.value.id === id && modal.value === 'supporters') details.value = data; } }
  catch(e) { if (current()) error.value = (e as Error).message; }finally { if (current()) busy.value = false; }
}
function detail(row: Row) { selected.value = row;open('detail'); }
function support(row: Row) { if (!member()) return;selected.value = row;open('pledge', { quantity: '', message: '', requestId: requestId() }); }
function review(row: Row) { selected.value = row;open('review', { status: 'approved', note: '' }); }
async function supporters(row: Row) {
  const current = scope.capture();selected.value = row;details.value = [];await open('supporters');
  const detailVersion = detailGeneration;
  const valid = () => current() && detailVersion === detailGeneration && selected.value.id === row.id && modal.value === 'supporters';
  if (!valid()) return;
  try { const data = await api('/crowdfunding/' + row.id + '/pledges');if (valid()) details.value = data; }catch(e) { if (valid()) error.value = (e as Error).message; }
}
function confirm(path: string, text: string, body?: Row) { open('confirm', { path, text, body }); }
function targetContact() { if (props.mode === 'contacts' && props.target && member()) open('contact', { recipientId: props.target.id, recipientName: props.target.name, contact: '', message: '' }); }
watch([() => props.mode, () => props.user?.id, () => props.manage, () => props.user?.status, () => props.user?.role], () => { scope.invalidate();++detailGeneration;busy.value = false;selected.value = {};form.value = {};error.value = '';dialog.value?.close();modal.value = '';message.value = '';++generation;rows.value = [];mine.value = [];pledges.value = [];managed.value = [];members.value = [];details.value = [];selected.value = {};form.value = {};dialog.value?.close();modal.value = '';message.value = '';tab.value = props.manage ? 'manage' : 'public';load(); }, { flush: 'sync' });
watch(() => props.target, targetContact);
onMounted(() => { load();targetContact(); });
</script>
<template><section><p v-if="error && !modal" class="form-error" role="alert">{{ error }}<button class="text-button" :disabled="loading" @click="load">重新加载</button></p><p v-if="loading && !modal" role="status">正在加载…</p><p v-if="message" class="status-note" role="status">{{ message }}</p><div class="filterbar"><div v-if="mode === 'crowdfunding'" class="chips"><button :class="{ selected: tab === 'public' }" @click="tab = 'public'">众筹项目</button><button v-if="user" :class="{ selected: tab === 'mine' }" @click="tab = 'mine'">我的发起</button><button v-if="user" :class="{ selected: tab === 'pledges' }" @click="tab = 'pledges'">我的支持</button><button v-if="staff" :class="{ selected: tab === 'manage' }" @click="tab = 'manage'">项目审核</button></div><p v-else class="form-tip">双方同意后才展示彼此愿意分享的联系方式。</p><button class="primary" @click="create"><Icon name="plus"/>{{ mode === 'contacts' ? '申请交换联系方式' : '发起众筹项目' }}</button></div>
  <p v-if="mode === 'crowdfunding'" class="support-note">支持物资、志愿服务与资金意向认领。资金数字仅表示支持意向，不代表已收款；本平台不在线收款、扣款或转账。</p>
  <template v-if="mode === 'crowdfunding' && tab !== 'pledges'"><div v-if="!loading && !error && !visible.length" class="empty"><Icon name="heart"/><h3>把每一份心意，汇成一份帮助</h3><p>发起真实项目，说明用途与目标，审核后邀请老乡自愿支持。</p></div><div class="cards-grid"><article v-for="row in visible" :key="row.id" class="post-card"><div class="hub-row"><span class="tag">{{ row.type }}</span><small>{{ row.status !== 'approved' ? statusNames[row.status] : row.ended ? '已结束' : '支持中' }}</small></div><h3><button class="plain" @click="detail(row)">{{ row.title }}</button></h3><p class="excerpt">{{ row.purpose }}</p><div class="progress-track"><span :style="{ width: Math.min(100, Number(row.pledgedQuantity) / Number(row.goal) * 100) + '%' }"></span></div><p class="progress-label">{{ row.type === '资金意向' ? '意向认领' : '已认领' }} {{ row.pledgedQuantity }} / {{ row.goal }} {{ row.unit }}</p><p v-if="row.type !== '资金意向'" class="meta">已核实交付 {{ row.deliveredQuantity }} {{ row.unit }} · {{ row.supporters }}位支持者</p><p class="meta">截止 {{ formatTime(row.endsAt) }} · {{ row.authorName }}</p><p v-if="row.reviewNote" class="form-tip">{{ row.reviewNote }}</p><div class="button-row"><button class="text-button" @click="detail(row)">项目详情</button><button v-if="row.status === 'approved' && !row.ended && Number(row.pledgedQuantity) < Number(row.goal)" class="outline" @click="support(row)">我来支持</button><button v-if="tab === 'manage' && row.status === 'pending'" class="text-button" @click="review(row)">审核项目</button><button v-if="row.authorId === user?.id || staff" class="text-button" @click="supporters(row)">支持记录</button><button v-if="!row.ended && (row.authorId === user?.id || staff)" class="text-button" @click="confirm('/crowdfunding/' + row.id + '/close', '停止接收新的支持，现有认领与交付记录保留。')">结束项目</button></div></article></div></template>
  <template v-if="mode === 'crowdfunding' && tab === 'pledges'"><div v-if="!loading && !error && !pledges.length" class="empty">还没有支持记录。</div><article v-for="row in pledges" :key="row.id" class="panel"><div class="hub-row"><h3>{{ row.projectTitle }}</h3><span class="tag">{{ row.projectType === '资金意向' && row.status === 'pledged' ? '意向已登记，未收款' : pledgeStates[row.status] }}</span></div><p class="prose">{{ row.quantity }} {{ row.unit }} · {{ row.projectType }}</p><p class="form-tip">{{ row.message }}</p><button v-if="row.status === 'pledged'" class="text-button" @click="confirm('/pledges/' + encodeURIComponent(row.id) + '/cancel', '确认取消本次认领？项目进度会同步更新。')">取消认领</button></article></template>
  <template v-if="mode === 'contacts'"><div v-if="!user" class="empty"><h3>保留边界，也让联系更方便</h3><p>加入并审核通过后，可以向老乡发起交换申请。</p><button class="primary" @click="emit('join')">登录 / 查看入会状态</button></div><div v-else-if="!rows.length" class="empty">还没有联系申请。可在老乡名录中选择希望联系的人。</div><article v-for="row in rows" :key="row.id" class="panel"><div class="hub-row"><h3>{{ row.requesterName }} ↔ {{ row.recipientName }}</h3><span class="tag">{{ contactStates[row.status] }}</span></div><p class="prose">{{ row.message }}</p><div v-if="row.status === 'accepted'" class="contact-reveal"><p>{{ row.requesterName }}：{{ row.requesterContact }}</p><p>{{ row.recipientName }}：{{ row.recipientContact }}</p></div><p v-else class="form-tip">尚未同意或已撤销，系统不展示对方联系方式。</p><div class="button-row"><template v-if="row.status === 'pending' && row.recipientId === user?.id"><button class="primary" @click="selected = row; open('acceptContact', { contact: '' })">同意并分享联系方式</button><button class="outline" @click="confirm('/contact-exchanges/' + row.id + '/action', '确认拒绝此联系申请？双方联系方式不会公开。', { action: 'reject' })">拒绝</button></template><button v-if="row.status === 'pending' && row.requesterId === user?.id" class="outline" @click="confirm('/contact-exchanges/' + row.id + '/action', '确认取消此联系申请？', { action: 'cancel' })">取消申请</button><button v-if="row.status === 'accepted'" class="text-button" @click="confirm('/contact-exchanges/' + row.id + '/action', '撤销后平台不再展示双方联系方式；对方已经保存的信息无法收回。', { action: 'revoke' })">撤销展示</button></div></article></template>
  <dialog ref="dialog" class="modal" aria-label="众筹与联系方式操作" @cancel.prevent="close"><div class="modal-inner"><header><h2>{{ modal === 'project' ? '发起自愿众筹项目' : modal === 'pledge' ? '登记支持意向' : modal === 'contact' ? '申请交换联系方式' : modal === 'acceptContact' ? '同意交换联系方式' : modal === 'review' ? '审核众筹项目' : modal === 'supporters' ? '支持与交付记录' : modal === 'confirm' ? '请确认' : selected.title }}</h2><button class="close-button" aria-label="关闭支持操作" :disabled="busy" @click="close">×</button></header><p v-if="error" class="form-error" role="alert">{{ error }}</p>
    <form v-if="modal === 'project'" @submit.prevent="act(() => api('/crowdfunding', 'POST', { ...form, endsAt: fromLocalInput(form.endsAt) }), '项目已提交审核')"><label>项目名称<input v-model="form.title" required minlength="2" maxlength="80"></label><div class="form-grid"><label>支持类型<select v-model="form.type"><option>物资</option><option>志愿服务</option><option>资金意向</option></select></label><label>目标数量<input v-model="form.goal" type="number" required min="0.01" max="1000000000" step="0.01"></label></div><label v-if="form.type === '物资'">数量单位<input v-model="form.unit" required maxlength="10" placeholder="如：件、本、份"></label><label>项目用途与使用计划<textarea v-model="form.purpose" required minlength="5" maxlength="1000" rows="3"></textarea></label><label>项目说明<textarea v-model="form.description" required minlength="10" maxlength="3000" rows="5"></textarea></label><label>支持截止时间（北京时间）<input v-model="form.endsAt" type="datetime-local" required></label><p class="support-note">{{ form.type === '资金意向' ? '单位为元；仅登记意向，不收款、不扣款、不提供收款码。' : form.type === '志愿服务' ? '单位为小时；实际服务由项目方核实记录。' : '请说明所需物资与交接方式，实际交付由项目方核实。' }}</p><label class="checkbox"><input v-model="form.consent" type="checkbox" required>我确认如实说明项目用途，并理解平台不在线收款。</label><button class="primary full" :disabled="busy">提交项目审核</button></form>
    <div v-if="modal === 'detail'"><span class="tag">{{ selected.type }} · {{ selected.authorName }}</span><h3 class="support-subtitle">用途与计划</h3><p class="prose">{{ selected.purpose }}</p><h3>项目说明</h3><p class="prose">{{ selected.description }}</p><p>{{ selected.type === '资金意向' ? '意向认领，非收款' : '认领进度' }}：{{ selected.pledgedQuantity }} / {{ selected.goal }} {{ selected.unit }}</p><p v-if="selected.type !== '资金意向'">已核实交付：{{ selected.deliveredQuantity }} {{ selected.unit }}</p><button v-if="selected.status === 'approved' && !selected.ended && Number(selected.pledgedQuantity) < Number(selected.goal)" class="primary full" @click="support(selected)">我来支持</button></div>
    <form v-if="modal === 'pledge'" @submit.prevent="act(() => api('/crowdfunding/' + selected.id + '/pledges', 'POST', form), selected.type === '资金意向' ? '资金意向已登记，未发生扣款' : '认领已记录')"><h3>{{ selected.title }}</h3><label>{{ selected.type === '资金意向' ? '资金支持意向（元）' : '认领数量（' + selected.unit + '）' }}<input v-model="form.quantity" type="number" required min="0.01" :max="Number(selected.goal) - Number(selected.pledgedQuantity)" step="0.01"></label><label>补充说明（仅项目方可见）<textarea v-model="form.message" maxlength="300" rows="3"></textarea></label><p class="support-note">{{ selected.type === '资金意向' ? '本次仅登记意向，不是支付或捐款到账，可在我的支持中取消。' : '请按项目约定完成交付；交付前可在我的支持中取消。' }}</p><button class="primary full" :disabled="busy">确认登记</button></form>
    <form v-if="modal === 'review'" @submit.prevent="act(() => api('/crowdfunding/' + selected.id + '/review', 'POST', form), '审核结果已保存')"><h3>{{ selected.title }}</h3><p>{{ selected.type }} · {{ selected.goal }}{{ selected.unit }} · {{ selected.authorName }}</p><p class="prose">{{ selected.purpose }}<br>{{ selected.description }}</p><label>审核结果<select v-model="form.status"><option value="approved">通过</option><option value="rejected">退回</option></select></label><label>审核说明<textarea v-model="form.note" :required="form.status === 'rejected'" :minlength="form.status === 'rejected' ? 2 : 0" maxlength="300" rows="3"></textarea></label><button class="primary full" :disabled="busy">确认审核</button></form>
    <div v-if="modal === 'supporters'"><p v-if="!loading && !error && !details.length" class="inline-empty">还没有支持记录。</p><article v-for="row in details" :key="row.id" class="record-row"><div><b>{{ row.supporterName }} · {{ row.quantity }}{{ row.unit }}</b><p>{{ row.message }}</p></div><span class="tag">{{ row.projectType === '资金意向' && row.status === 'pledged' ? '资金意向，未收款' : pledgeStates[row.status] }}</span><button v-if="row.projectType !== '资金意向' && row.status === 'pledged'" class="text-button" @click="act(() => api('/pledges/' + encodeURIComponent(row.id) + '/deliver', 'POST'), '实际交付已记录', true)">核实已交付</button></article></div>
    <form v-if="modal === 'contact'" @submit.prevent="act(() => api('/contact-exchanges', 'POST', form), '联系申请已发出，同意后可查看对方信息')"><label v-if="!form.recipientName">选择老乡<select v-model="form.recipientId" required><option disabled value="">从自愿公开名录的会员中选择</option><option v-for="member in members" :key="member.id" :value="member.id">{{ member.name }} · {{ member.hometown }} · {{ member.district }}</option></select></label><h3 v-else>联系 {{ form.recipientName }}</h3><label>打个招呼，说明来意<textarea v-model="form.message" required minlength="5" maxlength="500" rows="4"></textarea></label><label>你愿意分享的联系方式<input v-model="form.contact" required minlength="2" maxlength="100" placeholder="手机号、微信号或邮箱，由你选择"></label><p class="form-tip">对方同意并提供自己的联系方式后，双方才可看到彼此的信息。可取消尚未处理的申请。</p><button class="primary full" :disabled="busy">发送联系申请</button></form>
    <form v-if="modal === 'acceptContact'" @submit.prevent="act(() => api('/contact-exchanges/' + selected.id + '/action', 'POST', { action: 'accept', contact: form.contact }), '双方联系方式已交换')"><h3>{{ selected.requesterName }}</h3><p class="prose">{{ selected.message }}</p><label>你愿意向对方分享的联系方式<input v-model="form.contact" required minlength="2" maxlength="100" placeholder="手机号、微信号或邮箱"></label><p class="form-tip">确认后，双方可以查看并保存彼此填写的信息。</p><button class="primary full" :disabled="busy">同意并分享</button></form>
    <div v-if="modal === 'confirm'"><p class="prose">{{ form.text }}</p><div class="button-row"><button class="outline" @click="close">返回</button><button class="primary" :disabled="busy" @click="act(() => api(form.path, 'POST', form.body), '操作已完成')">确认</button></div></div>
  </div></dialog>
</section></template>
<style scoped>
.hub-row{display:flex;justify-content:space-between;gap:15px;align-items:center}.support-note{font-size:12px;background:#f6f2e9;border-left:3px solid #ccb48a;color:#9a815d;padding:13px 16px;margin:20px 0}.progress-track{height:7px;border-radius:7px;background:#e8efeb;overflow:hidden;margin-top:24px}.progress-track>span{display:block;height:100%;background:#4d9582;border-radius:7px}.progress-label{font-size:12px;color:#5b8777;margin-top:10px}.support-subtitle{margin-top:22px}.contact-reveal{padding:20px;background:#edf5f1;border-radius:7px;overflow-wrap:anywhere}.contact-reveal p{margin:5px 0;color:#517f6e}
</style>
